module legacy_resources;
pub struct Packet<T:wire>{data:T;scale:f64;}
fn identity<T:wire>(value:T)->T{return unwrap(decode_json<T>(encode_json(value)));}
fn capture(value:bytes)->(fn()->bytes){return fn()->bytes{return value;};}
server fn preserved_file(path:str)->result<bytes>!{fs}{return file_read_bytes(path);}
server fn reader()->(server fn(str)->result<bytes>!{fs}){return preserved_file;}
fn main()->unit!{io}{
 let original:bytes=unwrap(bytes([0,255,128,65]));
 print(identity(Packet<bytes>(capture(original)(),1.25)));
 print(unwrap(decode_utf8(utf8_bytes("Я\u0000🧠"))));
}
test fn preserved()->unit{
 let original:bytes=unwrap(bytes([0,255,128,65]));
 assert(capture(original)()==original);
 assert(identity(Packet<bytes>(original,1.25)).data==original);
 assert(encode_base64(slice(original,1,2))=="/4A=");
}
